solution:
import { useState } from 'react';

export function useNumberInput({ initial, step = 1, min = -Infinity, max = Infinity }) {
  const [value, setValue] = useState(initial);
  const clamp = (v) => Math.min(Math.max(v, min), max);
  return {
    value,
    increment: () => setValue(v => clamp(v + step)),
    decrement: () => setValue(v => clamp(v - step)),
    set: (n) => setValue(clamp(n)),
  };
}
